// ============================================
// FILTRE ET GÉNÉRATION DE SUJETS D'ARTICLES
// ============================================
// Ce nœud analyse les titres des actualités et
// génère des sujets d'articles adaptés à WAYS.
// Modifiez les mots-clés selon vos besoins.

const MOTS_CLES = [
  // Digital & IA
  'intelligence artificielle', 'ia', 'digital', 'numérique', 'tech', 'startup',
  'automatisation', 'chatbot', 'data', 'cloud', 'logiciel', 'erp', 'crm',
  // Business & Stratégie
  'entreprise', 'pme', 'tpe', 'management', 'stratégie', 'croissance',
  'financement', 'investissement', 'export', 'marché', 'compétitivité',
  // BTP & Immobilier
  'btp', 'construction', 'immobilier', 'infrastructure', 'chantier', 'bâtiment',
  // Formation
  'formation', 'compétence', 'emploi', 'talent', 'rh', 'ressources humaines',
  // Afrique & CI
  'afrique', 'côte d\'ivoire', 'abidjan', 'uemoa', 'cedeao', 'afrique de l\'ouest'
];

const CATEGORIES = {
  'ia': 'IA & Digital', 'intelligence artificielle': 'IA & Digital', 'digital': 'IA & Digital',
  'numérique': 'IA & Digital', 'tech': 'IA & Digital', 'startup': 'IA & Digital',
  'automatisation': 'IA & Digital', 'data': 'IA & Digital', 'cloud': 'IA & Digital',
  'logiciel': 'IA & Digital', 'erp': 'IA & Digital', 'chatbot': 'IA & Digital',
  'management': 'Stratégie', 'stratégie': 'Stratégie', 'entreprise': 'Stratégie',
  'pme': 'Stratégie', 'croissance': 'Stratégie', 'investissement': 'Stratégie',
  'btp': 'BTP', 'construction': 'BTP', 'immobilier': 'BTP', 'infrastructure': 'BTP',
  'formation': 'Formation', 'compétence': 'Formation', 'talent': 'Formation', 'rh': 'Formation'
};

const items = $input.all();
const sujets = [];
const vus = new Set();

for (const item of items) {
  const titre = (item.json.title || '').toLowerCase();
  const description = (item.json.contentSnippet || item.json.summary || '').toLowerCase();
  const texte = titre + ' ' + description;

  // Vérifier si l'article est pertinent
  const motTrouve = MOTS_CLES.find(mot => texte.includes(mot));
  if (!motTrouve) continue;

  // Déterminer la catégorie
  let categorie = 'Stratégie';
  for (const [mot, cat] of Object.entries(CATEGORIES)) {
    if (texte.includes(mot)) { categorie = cat; break; }
  }

  // Générer un sujet adapté au contexte WAYS
  const titreOriginal = item.json.title || '';
  const sujet = `${titreOriginal} — Enjeux et opportunités pour les entreprises en Côte d'Ivoire`;

  // Éviter les doublons
  const cle = sujet.slice(0, 50).toLowerCase();
  if (vus.has(cle)) continue;
  vus.add(cle);

  sujets.push({
    json: {
      topic: sujet,
      category: categorie,
      keywords: [motTrouve, 'Côte d\'Ivoire', 'Afrique de l\'Ouest', categorie.toLowerCase()],
      source: 'n8n-veille-auto'
    }
  });

  // Limiter à 5 sujets par session
  if (sujets.length >= 5) break;
}

if (sujets.length === 0) {
  return [{ json: { skip: true, message: 'Aucun sujet pertinent trouvé cette semaine.' } }];
}

return sujets;
